import net.minecraft.client.input.KeyEvent;
import java.nio.file.*;
import java.util.*;

final class MapCommanderAvailabilityTest {
    private MapCommanderAvailabilityTest() {}
    private static Assessment result(Check q,Map<String,Decision> values){return new Assessment(q.token(),q.revision(),q.sequence(),q.request(),values);}
    static void run(ClientGameTestContext game,ProtocolMenuView menu,String directory)throws java.io.IOException {
        var source=new Snapshot(Files.readString(Path.of(directory,"kor-command-panel-army.json"))).view();var queries=new ArrayList<Check>();var commands=new ArrayList<Command>();var issued=new Context[1];String denied="배정 해제할 대상이 없습니다.";
        try {
            game.getInput().resizeWindow(1280,720);
            game.runOnClient(client->{
                client.options.guiScale().set(2);ClientCampaignHud.accept(ProtocolHudPayloads.State.of("KOR",menu.hud()));MapCommanderOrders.reset();MapCommanderHud.reset();MapUnitHud.reset();MapCommanderHud.requestObserver=null;MapCommanderAvailability.queryObserver=queries::add;MapCommanderOrders.selectionObserver=q->{};MapCommanderOrders.commandObserver=commands::add;
                MapCommanderHud.accept(new View(source.country(),client.level.dimension().identifier().toString(),source.branch(),source.cards(),source.wings()));issued[0]=new Context(UUID.randomUUID().toString(),10,"KOR",client.level.dimension().identifier().toString(),"");MapCommanderOrders.accept(issued[0]);var army=source.cards().stream().filter(c->c.role()==Mode.ASSIGN_ARMY&&c.panel()!=null&&!c.panel().members().isEmpty()).findFirst().orElseThrow();MapCommanderPanels.select(army.id(),false);MapCommanderOrders.selectionChanged();
                if(MapCommanderAvailability.reason("LAND/FRONT").isEmpty())throw new AssertionError("Supported server requires current selection assessment before command entry");
                var q=queries.getLast();var rejected=Map.of("ARMY/UNASSIGN_UNITS",new Decision(false,false,denied),"LAND/ASSIGN_UNITS",new Decision(false,false,"선택한 사단을 배정할 수 없습니다."),"LAND/FRONT",new Decision(true,true,""),"ARMY/ACTIVATE",new Decision(false,false,"선택한 군에 작전 계획이 없습니다."),"ARMY/REMOVE",new Decision(false,false,"선택한 군에 작전 계획이 없습니다."),"LAND/DELETE_PLAN",new Decision(true,true,""));MapCommanderAvailability.accept(result(q,rejected));
                if(!MapCommanderAvailability.reason("ARMY/UNASSIGN_UNITS").equals(denied)||!MapCommanderAvailability.tooltip("ARMY/UNASSIGN_UNITS","원본\n\n문장").startsWith("원본\n\n문장\n\n")||!MapCommanderAvailability.tooltip("LAND/FRONT","원본\n\n문장").equals("원본\n\n문장"))throw new AssertionError("Original tooltip spacing and authoritative reasons must survive decoration");
                if(MapCommanderAvailability.reason("ARMY/ACTIVATE",MapCommanderPanels.armyIds()).isEmpty()||!MapCommanderAvailability.reason("ARMY/ACTIVATE",List.of("different_army")).isEmpty())throw new AssertionError("Card request must use availability only for its exact selected army scope");
                MapCommanderAvailability.accept(new Assessment(q.token(),q.revision(),q.sequence(),q.request()-1,Map.of("ARMY/UNASSIGN_UNITS",new Decision(true,false,""))));if(!MapCommanderAvailability.reason("ARMY/UNASSIGN_UNITS").equals(denied))throw new AssertionError("Older request cannot enable current disabled action");
            });
            game.setScreen(ScreenMapCursor::new);game.waitTicks(2);
            game.runOnClient(client->{
                var delete=MapCommanderPanels.hits().stream().filter(h->h.tip().contains("우클릭: 선택한 군에 작전 계획이 없습니다.")).findFirst().orElseThrow();int bulkBefore=commands.size();MapCommanderPanels.click(delete.x()+delete.w()/2.,delete.y()+delete.h()/2.,InputConstants.MOUSE_BUTTON_RIGHT,false);if(commands.size()!=bulkBefore)throw new AssertionError("Disabled bulk delete must not issue direct removal or delete selected units");
                var hit=MapCommanderPanels.hits().stream().filter(h->h.tip().contains(denied)).findFirst().orElseThrow();int before=commands.size();MapCommanderHud.clickAt(hit.x()+hit.w()/2.,hit.y()+hit.h()/2.);client.gui.screen().keyPressed(new KeyEvent(InputConstants.KEY_H,0,InputConstants.MOD_CONTROL));client.gui.screen().keyPressed(new KeyEvent(InputConstants.KEY_LCONTROL,0,InputConstants.MOD_CONTROL));if(commands.size()!=before||MapCommanderOrders.pointMode())throw new AssertionError("Disabled button, Ctrl+H and held Ctrl must obey the same assessment");client.gui.screen().keyReleased(new KeyEvent(InputConstants.KEY_LCONTROL,0,0));
            });
            var hover=game.computeOnClient(client->MapCommanderPanels.hits().stream().filter(h->h.tip().contains(denied)).findFirst().orElseThrow());game.getInput().setCursorPos((hover.x()+hover.w()/2.)*2,(hover.y()+hover.h()/2.)*2);game.waitTicks(2);game.takeScreenshot("hoi-command-availability-disabled-gui2");
            String[] abilityReasons={"선택 사단의 지원중대 과금 규칙은 원본 관측 대기 중입니다.","스킬 비용 보정의 합산·반올림 규칙은 원본 관측 대기 중입니다.","스킬 종료 후 재사용 시각은 원본 관측 대기 중입니다."};String[] cases={"support","cost","reuse"};
            for(int i=0;i<abilityReasons.length;i++){
                String reason=abilityReasons[i];game.runOnClient(client->MapCommanderAvailability.accept(result(queries.getLast(),Map.of("ABILITY/STAFF_OFFICE_PLAN",new Decision(false,false,reason)))));game.waitTicks(2);
                var ability=game.computeOnClient(client->MapCommanderPanels.hits().stream().filter(h->h.icon().equals("ability_staff_office_plan")).findFirst().orElseThrow());
                game.runOnClient(client->{if(!ability.tip().contains(reason)||!MapCommanderAvailability.reason("ABILITY/STAFF_OFFICE_PLAN",MapCommanderPanels.commandSelection()).equals(reason))throw new AssertionError("Skill tooltip and exact-selection gate must retain the server reason");var screen=client.gui.screen();int before=commands.size();MapCommanderHud.clickAt(ability.x()+ability.w()/2.,ability.y()+ability.h()/2.);if(commands.size()!=before||client.gui.screen()!=screen)throw new AssertionError("Unresolved skill must neither execute nor open an information window");});
                game.getInput().setCursorPos((ability.x()+ability.w()/2.)*2,(ability.y()+ability.h()/2.)*2);game.waitTicks(2);game.takeScreenshot("hoi-officer-skill-disabled-"+cases[i]+"-gui2");
            }
            Map<String,Decision> rejectedSkills=new com.google.gson.Gson().fromJson(Files.readString(Path.of(directory,"kor-selected-skill-rejections.json")),new com.google.gson.reflect.TypeToken<Map<String,Decision>>(){}.getType());
            for(String skill:List.of("FORCE_ATTACK","LAST_STAND","EXTRA_SUPLIES")){
                String action="ABILITY/"+skill;var decision=rejectedSkills.get(action);if(decision==null||decision.enabled()||decision.reason().isBlank())throw new AssertionError("Actual server fixture must reject incomplete skill "+action);game.runOnClient(client->MapCommanderAvailability.accept(result(queries.getLast(),rejectedSkills)));game.waitTicks(2);
                var ability=game.computeOnClient(client->MapCommanderPanels.hits().stream().filter(h->h.icon().equals("ability_"+skill.toLowerCase(Locale.ROOT))).findFirst().orElseThrow());game.runOnClient(client->{if(!ability.tip().contains(decision.reason())||!MapCommanderAvailability.reason(action,MapCommanderPanels.commandSelection()).equals(decision.reason()))throw new AssertionError("Incomplete skill must retain its actual server rejection reason");var screen=client.gui.screen();int before=commands.size();MapCommanderHud.clickAt(ability.x()+ability.w()/2.,ability.y()+ability.h()/2.);if(commands.size()!=before||client.gui.screen()!=screen)throw new AssertionError("Incomplete skill must not issue an execution request or open a success window");});game.getInput().setCursorPos((ability.x()+ability.w()/2.)*2,(ability.y()+ability.h()/2.)*2);game.waitTicks(2);game.takeScreenshot("hoi-officer-skill-unimplemented-"+skill.toLowerCase(Locale.ROOT)+"-gui2");
            }
            game.runOnClient(client->{
                var old=queries.getLast();var army=source.cards().stream().filter(c->MapCommanderPanels.selected(c.id())).findFirst().orElseThrow();var member=army.panel().members().getFirst();MapUnitHud.clearSelection();MapCommanderOrders.selectionChanged();var changed=queries.getLast();if(changed.request()==old.request()||!MapCommanderPanels.commandSelection().isEmpty())throw new AssertionError("Actual deselection must publish an empty selection and invalidate availability");MapUnitHud.selectDivisions(List.of(member.id()),false);MapCommanderOrders.selectionChanged();var q=queries.getLast();if(q.request()==old.request())throw new AssertionError("Changing selected units must request new availability");MapCommanderAvailability.accept(result(old,Map.of("ARMY/UNASSIGN_UNITS",new Decision(true,false,""))));if(MapCommanderAvailability.reason("ARMY/UNASSIGN_UNITS").isEmpty())throw new AssertionError("Stale selection response cannot enable commands");
                MapCommanderAvailability.accept(result(q,Map.of("LAND/FRONT",new Decision(true,true,""),"LAND/ASSIGN_UNITS",new Decision(true,true,""))));int before=commands.size();MapCommanderOrders.land("FRONT",MapCommanderPanels.armyIds());if(commands.size()!=before+1||!commands.getLast().action().equals("LAND/FRONT"))throw new AssertionError("Enabled mode entry must send exactly one actual command");
                MapCommanderOrders.accept(new Context(issued[0].token(),11,"KOR",issued[0].dimension(),"LAND/FRONT"));if(MapCommanderAvailability.reason("LAND/FRONT").isEmpty())throw new AssertionError("New command revision invalidates old availability");MapCommanderAvailability.accept(result(q,Map.of("LAND/FRONT",new Decision(true,true,""))));if(MapCommanderAvailability.reason("LAND/FRONT").isEmpty())throw new AssertionError("Old revision reply cannot reenable current command");
                MapCommanderAvailability.accept(result(queries.getLast(),Map.of("LAND/ASSIGN_UNITS",new Decision(true,true,""),"LAND/FRONT",new Decision(true,true,""))));MapCommanderOrders.held("ASSIGN_UNITS");if(!MapCommanderOrders.pointMode())throw new AssertionError("Allowed held assignment must enter point mode");MapCommanderOrders.map(List.of(new Ray(0,-1,0)));MapCommanderOrders.discardHeld();MapCommanderOrders.route(new Open(Mode.ARMY_TOOLBAR,"UNASSIGN_UNITS",MapCommanderPanels.commandSelection()));
                MapCommanderOrders.accept(new Context(issued[0].token(),12,"KOR",issued[0].dimension(),"LAND/ASSIGN_UNITS"));if(!commands.getLast().action().equals("CANCEL"))throw new AssertionError("Interrupted held mode must first cancel");MapCommanderOrders.accept(new Context(issued[0].token(),13,"KOR",issued[0].dimension(),""));int cancelled=commands.size();MapCommanderAvailability.accept(result(queries.getLast(),Map.of("ARMY/UNASSIGN_UNITS",new Decision(false,false,denied))));if(commands.size()!=cancelled)throw new AssertionError("Denied queued action cannot execute after cancellation");MapCommanderOrders.accept(new Context(issued[0].token(),14,"KOR",issued[0].dimension(),""));MapCommanderAvailability.accept(result(queries.getLast(),Map.of("ARMY/UNASSIGN_UNITS",new Decision(true,false,""))));if(commands.size()!=cancelled)throw new AssertionError("Later availability cannot revive an already denied queued action");MapCommanderOrders.reset();MapCommanderAvailability.accept(result(queries.getLast(),Map.of("LAND/FRONT",new Decision(true,true,""))));if(MapCommanderOrders.valid())throw new AssertionError("Revoked session must remain revoked");
            });
            armyAirScope(game,directory,queries,commands);
        }finally{game.runOnClient(client->{MapCommanderAvailability.queryObserver=null;MapCommanderOrders.commandObserver=null;MapCommanderOrders.selectionObserver=null;MapCommanderOrders.reset();MapCommanderHud.requestObserver=null;MapCommanderHud.reset();MapUnitHud.reset();});}
    }
    private static void armyAirScope(ClientGameTestContext game,String directory,List<Check> queries,List<Command> commands)throws java.io.IOException {
        var source=new Snapshot(Files.readString(Path.of(directory,"kor-command-panel-army-air-attached.json"))).view();
        var wing=source.wings().stream().filter(value->value.data()!=null&&!value.data().attachedArmy().isEmpty()).findFirst().orElseThrow();var army=source.cards().stream().filter(card->card.id().equals(wing.data().attachedArmy())).findFirst().orElseThrow();
        game.runOnClient(client->{
            MapCommanderOrders.reset();MapCommanderHud.reset();MapUnitHud.reset();String dimension=client.level.dimension().identifier().toString();MapCommanderHud.accept(new View(source.country(),dimension,source.branch(),source.cards(),source.wings()));MapCommanderOrders.accept(new Context(UUID.randomUUID().toString(),0,source.country(),dimension,""));MapCommanderPanels.select(army.id(),false);
            var armyQuery=queries.getLast();var allowed=Map.of("LAND/FRONT",new Decision(true,true,""),"ARMY/ACTIVATE",new Decision(true,false,""),"ABILITY/STAFF_OFFICE_PLAN",new Decision(true,false,""));MapCommanderAvailability.accept(result(armyQuery,allowed));if(!MapCommanderAvailability.reason("LAND/FRONT").isEmpty())throw new AssertionError("Army assessment must initially enable its valid land command");
            MapCommanderPanels.showWings(List.of(wing.id()));var airQuery=queries.getLast();if(!airQuery.armies().isEmpty()||MapCommanderPanels.armyInput()||!MapCommanderPanels.commandSelection().equals(List.of("air/"+wing.id())))throw new AssertionError("Attached air must publish its exact selection without the previously selected army scope");MapCommanderAvailability.accept(result(airQuery,Map.of("AIR/HOLD",new Decision(true,false,""))));
            String reason="비행단을 선택한 상태입니다. 군이나 사단을 선택하세요.";int before=commands.size();
            for(String action:List.of("LAND/FRONT","ARMY/ACTIVATE","ABILITY/STAFF_OFFICE_PLAN")){
                if(!MapCommanderAvailability.reason(action).equals(reason)||!MapCommanderAvailability.reason(action,List.of("different_army")).equals(reason)||!MapCommanderAvailability.tooltip(action,"원본\n\n설명").startsWith("원본\n\n설명\n\n"))throw new AssertionError("Air selection must disable every land command scope while preserving original tooltip spacing");
                if(MapCommanderOrders.send(action,List.of(army.id()),List.of()))throw new AssertionError("Air selection must not send a land request from a retained army card");
            }
            if(commands.size()!=before||!MapCommanderAvailability.reason("AIR/HOLD",List.of(wing.id())).isEmpty())throw new AssertionError("The air assessment must retain its allowed air action without emitting land requests");
            MapCommanderAvailability.queryObserver=null;try{if(!MapCommanderAvailability.reason("LAND/FRONT").equals(reason))throw new AssertionError("Branch mismatch must also reject without an availability transport");}finally{MapCommanderAvailability.queryObserver=queries::add;}
            MapCommanderPanels.select(army.id(),false);if(!MapCommanderPanels.armyInput()||!MapCommanderPanels.selectedWingIds().isEmpty()||MapCommanderAvailability.reason("LAND/FRONT").isEmpty())throw new AssertionError("Returning to the army must clear wing selection and await its new assessment");MapCommanderAvailability.accept(result(queries.getLast(),allowed));if(!MapCommanderAvailability.reason("LAND/FRONT").isEmpty()||!MapCommanderOrders.send("LAND/FRONT",List.of(army.id()),List.of())||commands.size()!=before+1||!commands.getLast().action().equals("LAND/FRONT"))throw new AssertionError("The refreshed army scope must execute its land command exactly once");
        });
    }
}
